#!/usr/bin/env node
// Gate: the image the world shares says the same thing as the page it shares.
//
//     node scripts/check-og-image.mjs       (part of `npm run lint`)
//
// The card is generated by `scripts/gen_og_image.mjs` from `lib/site.ts`, and
// it carries the title it was drawn from in a `tEXt` chunk — the PNG format's
// own text field. This reads that chunk back and compares it against the same
// constants, so the check is between two readings of one source rather than
// between a picture and a guess.
//
// What it catches: a title changed in `lib/site.ts` while the card was left
// behind (the card said "LiteSPM Market" for months, a name no page used, and
// the accessible text of the card said a fourth thing), a card that is not
// 1200×630 — the dimensions Open Graph and every scraper expect — and a
// missing touch icon, which leaves iOS to screenshot the page for a home
// screen icon.
//
// Usage: node scripts/check-og-image.mjs [--root <dir>]

import { readFileSync, existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import ts from "typescript";

const here = path.dirname(fileURLToPath(import.meta.url));
const rootArg = process.argv.indexOf("--root");
const webRoot = rootArg === -1 ? path.dirname(here) : path.resolve(process.argv[rootArg + 1]);

function fail(message) {
  console.error(`FAIL og image — ${message}`);
  process.exit(1);
}

/** `lib/site.ts`, transpiled — the source the card is generated from. */
async function siteConstants() {
  const modulePath = path.join(webRoot, "lib", "site.ts");
  if (!existsSync(modulePath)) fail(`lib/site.ts is not at ${modulePath}`);
  const transpiled = ts.transpileModule(readFileSync(modulePath, "utf8"), {
    compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2022 },
    fileName: modulePath,
  }).outputText;
  return import(`data:text/javascript;base64,${Buffer.from(transpiled).toString("base64")}`);
}

/** Walk the PNG's chunk list; return its IHDR size and its `tEXt` pairs. */
function readPng(file) {
  const buffer = readFileSync(file);
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  if (!buffer.subarray(0, 8).equals(signature)) fail(`${file} is not a PNG`);
  const size = { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
  const text = {};
  let offset = 8;
  while (offset + 8 <= buffer.length) {
    const length = buffer.readUInt32BE(offset);
    const type = buffer.subarray(offset + 4, offset + 8).toString("latin1");
    if (type === "tEXt" || type === "iTXt") {
      const body = buffer.subarray(offset + 8, offset + 8 + length);
      const nul = body.indexOf(0);
      if (nul <= 0) continue;
      const keyword = body.subarray(0, nul).toString("latin1");
      if (type === "tEXt") {
        text[keyword] = body.subarray(nul + 1).toString("latin1");
      } else {
        // keyword \0 flag method language\0 translated\0 text
        let cursor = nul + 1 + 2;
        while (cursor < body.length && body[cursor] !== 0) cursor += 1; // language
        cursor += 1;
        while (cursor < body.length && body[cursor] !== 0) cursor += 1; // translated keyword
        cursor += 1;
        text[keyword] = body.subarray(cursor).toString("utf8");
      }
    }
    offset += 12 + length;
    if (type === "IEND") break;
  }
  return { size, text };
}

async function main() {
  const site = await siteConstants();
  if (!site.SITE_TITLE || !site.SITE_NAME) fail("lib/site.ts exports no SITE_TITLE / SITE_NAME");

  const ogPath = path.join(webRoot, "public", "og.png");
  if (!existsSync(ogPath)) {
    fail("public/og.png is missing — run `npm run gen:og`");
  }
  const og = readPng(ogPath);
  if (og.size.width !== 1200 || og.size.height !== 630) {
    fail(`public/og.png is ${og.size.width}x${og.size.height}; Open Graph cards are 1200x630`);
  }
  if (!og.text.Title) {
    fail(
      "public/og.png carries no Title text field — it was not drawn by " +
        "scripts/gen_og_image.mjs, so nothing can tell what it claims to say"
    );
  }
  if (og.text.Title !== site.SITE_TITLE) {
    fail(
      `public/og.png says "${og.text.Title}" but the site says "${site.SITE_TITLE}" — ` +
        "regenerate it with `npm run gen:og`"
    );
  }
  if (og.text.Software !== site.SITE_NAME) {
    fail(`public/og.png names "${og.text.Software}"; the site's name is "${site.SITE_NAME}"`);
  }

  const iconPath = path.join(webRoot, "app", "apple-icon.png");
  if (!existsSync(iconPath)) {
    fail("app/apple-icon.png is missing — run `npm run gen:og` (iOS falls back to a page screenshot without it)");
  }
  const icon = readPng(iconPath);
  if (icon.size.width !== 180 || icon.size.height !== 180) {
    fail(`app/apple-icon.png is ${icon.size.width}x${icon.size.height}, not 180x180`);
  }

  console.log(
    `OK og image — public/og.png is 1200x630 and its title matches the site's ` +
      `("${site.SITE_TITLE}"); app/apple-icon.png is 180x180`
  );
}

main().catch((error) => {
  fail(error instanceof Error ? error.message : String(error));
});
